using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.Semilinear;

internal sealed class ChartFieldDegreeDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The least field generated by normalized coordinates controls full semilinear orbit size.",
        H("The coordinate field and Frobenius isotropy"),
        Blocks(Describe.Lean(
            DescribeId.Create("weighted-chart-generated-field-degree"),
            DeclarationHandle.Create("D5/S3/FiniteGroups/Semilinear/ChartFieldDegree.chart_field_degree"),
            H("Actual fixing subgroup and full ambient orbit"), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(
                Paragraph(Text("For a finite field K over ZMod p of cardinality p to the power n, form the actual intermediate field L=IntermediateField.adjoin (ZMod p) (Set.range (normalize w A)), and put e=Module.finrank (ZMod p) L. The theorem identifies the actual normalized-coordinate stabilizer with L.fixingSubgroup, proves e divides n, and proves that the stabilizer of the original vector A in the full weighted coefficient space has cardinal n/e and its full semilinear orbit has cardinal (p to the power n minus one) times e. The endpoint counts the native ambient orbit of A.val under weightedAction, not just a residual Galois orbit or a chart quotient.")),
                Paragraph(Text("Fixing the tuple is fixing every generator. The native adjoin universal property extends this to fixing its entire generated field. The chart group isomorphism and the equality of chart and ambient stabilizer subgroups then identify the actual semilinear isotropy with Gal(K/L). Mathlib Galois correspondence gives its cardinality [K:L], and the tower law gives e[K:L]=n. Native orbit-stabilizer and the actual semidirect-product group cardinality (card K minus one)n give the full orbit size. No field-degree, fixed-field or orbit-count conclusion is assumed as a premise.")),
                Paragraph(Text("This is the field-of-definition interpretation of Frobenius dynamics: the normalized tuple has least field L, and in a finite field its least Frobenius period is e. All automorphisms fixing that field give isotropy, so smaller fields give larger stabilizers and shorter orbits. The Lean theorem proves the fixing-subgroup and degree/cardinality chain; the least-positive-period wording is its standard finite-field interpretation, not an additional retained periodic-point theorem.")),
                Paragraph(Text("J need not be finite. Empty J and the all-zero normalized tuple both generate the base field, so e=1; the stabilizer has cardinal n and the ambient orbit has cardinal p to the power n minus one. All primes, including two, are covered. As application checks, the original n=2 chart has no residual coordinates and gives orbit size eight over F9; for the n=3 weights (1,7) over F27, residual degrees one and three give orbit sizes 26 and 78. The chart has eleven classes and the full original problem thirteen, with two classes on the omitted boundary. These examples are applications, not replacement classification targets.")),
                Paragraph(Text("For fixed finite residual dimension r, ordinary finite-field Frobenius counting gives C_e=(1/e) times the sum over d dividing e of Moebius(e/d) p to the power dr. Summing over e dividing n gives the usual totient average (1/n) times the sum over d dividing n of totient(n/d) p to the power dr. These are standard Moebius inversion and Burnside consequences, retained here as exposition rather than separate theorem families. Closed points of affine r-space are Frobenius orbits, and for fixed r its zeta function is 1/(1-p to the power r times T). Sources for this standard interpretation include Bjorn Poonen, Rational Points on Varieties, section 5 (https://math.mit.edu/~poonen/papers/aws2014.pdf), and Daqing Wan, Lectures on Zeta Functions over Finite Fields (https://www.math.uci.edu/~dwan/gottingen.pdf).")),
                Paragraph(Text("For original jets the weight-one coordinate exists only for n at least two, and removing it leaves r=n-2. Varying n therefore varies the dimension and does not describe the extension-field counts of one fixed variety or one zeta function. Raw orbit classes, coarse rational points and reciprocal-stabilizer mass remain distinct. The retained proof adds the actual coordinate-field relationship to the chart bridge, reusing standard finite Galois theory and orbit-stabilizer without a novelty claim."))),
            DescribeRole.Theorem))));
}
